<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A')
const hold=ref('after')
const selected=ref(0)
const state=ref('ready')
const labels=['Jan','Feb','Mar','Apr','May','Jun']
const primary=computed(()=>dataset.value==='A'?[35,48,41,61,56,74]:dataset.value==='B'?[42,36,55,48,72,64]:[0,0,0,0,0,0])
const x=(i:number)=>40+i*48
const y=(v:number)=>170-v*1.4
const step=computed(()=>primary.value.map((v,i)=>i?(hold.value==='after'?` H${x(i)} V${y(v)}`:` V${y(v)} H${x(i)}`):`M${x(i)},${y(v)}`).join(''))
function reset(){dataset.value='A';hold.value='after';selected.value=0;state.value='ready'}
</script>
<template>
<section class="step-chart-demo" aria-label="Local step line chart example"><p>Synthetic monthly units. Values hold between monthly boundaries. Select which side of each boundary changes.</p><div class="step-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="zero">All zero</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><label>Boundary convention<select v-model="hold"><option value="after">Step after</option><option value="before">Step before</option></select></label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><div class="step-legend"><span>Single series: Primary units</span><span>{{ hold==='after'?'Hold previous value to next boundary':'Use next value after previous boundary' }}</span></div><svg :key="dataset+'-'+hold" viewBox="0 0 320 210" role="img" aria-label="Synthetic monthly units, January to June, fixed scale 0 to 100. Step line holds values between boundaries; exact observations are in the table below."><g v-for="tick in [0,25,50,75,100]" :key="tick"><line x1="36" x2="292" :y1="y(tick)" :y2="y(tick)" class="step-grid"/><text x="4" :y="y(tick)+4">{{ tick }}</text></g><text v-for="(label,i) in labels" :key="label" :x="x(i)" y="194" text-anchor="middle">{{ label }}</text><path :d="step" class="step-primary"/><circle v-for="(v,i) in primary" :key="i" :cx="x(i)" :cy="y(v)" :r="selected===i?5:3" class="step-dot"/></svg><div role="group" aria-label="Select month" class="step-months"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @click="selected=i" @focus="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: Primary {{ primary[selected] }} units.</p><table class="step-data"><caption>Exact sample values, dataset {{ dataset }}</caption><thead><tr><th scope="col">Month</th><th scope="col">Primary units</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ primary[i] }}</td></tr></tbody></table></template><p v-else role="status" class="step-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample observations in this state. Choose Ready to recover.' }}</p></section>
</template>
<style scoped>
.step-chart-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.step-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.step-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.step-chart-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.step-chart-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.step-chart-demo :is(button,select,input):focus-visible{outline:2px solid var(--vp-c-brand-1);outstep-offset:3px}.step-legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:18px;font-size:12px}.step-chart-demo svg{display:block;width:100%;height:auto;max-height:330px;margin:16px 0;animation:step-chart-in .2s ease-out}.step-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 4}.step-chart-demo svg text{fill:var(--vp-c-text-2);font-size:10px}.step-primary,.step-secondary{fill:none;stroke:var(--vp-c-brand-1);stroke-width:2.5}.step-dot{fill:var(--vp-c-brand-1);stroke:var(--vp-c-bg);stroke-width:1}.step-months{display:flex;gap:6px;flex-wrap:wrap}.step-months button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.step-data{display:table!important;width:100%;font-size:12px}.step-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.step-data :is(td,th){padding:6px 8px!important}.step-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes step-chart-in{from{opacity:.4}to{opacity:1}}@media(prefers-reduced-motion:reduce){.step-chart-demo svg{animation:none}}
</style>
